INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6d942937-d3e2-5a87-a7f0-539d2ea3fc82', 'Corporate Governance Principles: A Japanese view', 'Corporate Governance Principles: A Japanese view', 'The principles in this document have been written to present a Japanese model of corporate governance. They place special emphasis on the importance of the shareholders, and on the board of directors, who function simultaneously as the shareholders'' delegates and as the promoters of the benefits of all concerned stakeholders.', 'The principles in this document have been written to present a Japanese model of corporate governance. They place special emphasis on the importance of the shareholders, and on the board of directors, who function simultaneously as the shareholders'' delegates and as the promoters of the benefits of all concerned stakeholders.', 'The principles in this document have been written to present a Japanese model of corporate governance. They place special emphasis on the importance of the shareholders, and on the board of directors, who function simultaneously as the shareholders'' delegates and as the promoters of the benefits of all concerned stakeholders.', 'Japan', 'climate', 'in_force', '1997-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_16', ARRAY['guidance_frameworks', 'sdg9', 'sdg16', 'disclosure', 'japan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('207a9129-b692-563e-85d0-a44598bcf8bb', 'Japan Urgent Recommendations Concerning Corporate Governance', 'Urgent Recommendations Concerning Corporate Governance 1997', 'This paper examines active ownership in Japan by an equity ownership service, Governance for Owners Japan (GOJ).', 'This paper examines active ownership in Japan by an equity ownership service, Governance for Owners Japan (GOJ).', 'This paper examines active ownership in Japan by an equity ownership service, Governance for Owners Japan (GOJ).', 'Japan', 'governance', 'in_force', '1997-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_22', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg16', 'japan', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3711561a-7cc5-58cf-ad81-fa788d16f2c6', 'Japan 1997 Law Environmental Impact Assessment Act', '1997 Law No. 81 Environmental Impact Assessment Act', 'The purpose of this Act is, in recognition of the fact that it is extremely important, in terms of protecting the environment. It details environmental impact assessment.', 'The purpose of this Act is, in recognition of the fact that it is extremely important, in terms of protecting the environment. It details environmental impact assessment.', 'The purpose of this Act is, in recognition of the fact that it is extremely important, in terms of protecting the environment. It details environmental impact assessment.', 'Japan', 'climate', 'in_force', '1997-01-01'::date, 'Japan', 'https://www.carrotsandsticks.org/policies/87_39', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'japan', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7fb864ff-f6c0-52c3-b059-67c063f4d0d5', 'Jersey Consultation on proposals regarding sustainable finance', 'Consultation on proposals regarding sustainable finance', 'Jersey seeks feedback on enhancing Codes of Practice for sustainability and business integrity risks in finance. The consultation aims to gather industry responses for regulatory adjustments, impacting individuals, law firms, and trust companies. Feedback deadline is July 4, 2025.', 'Jersey seeks feedback on enhancing Codes of Practice for sustainability and business integrity risks in finance. The consultation aims to gather industry responses for regulatory adjustments, impacting individuals, law firms, and trust companies. Feedback deadline is July 4, 2025.', 'Jersey seeks feedback on enhancing Codes of Practice for sustainability and business integrity risks in finance. The consultation aims to gather industry responses for regulatory adjustments, impacting individuals, law firms, and trust companies. Feedback deadline is July 4, 2025.', 'Jersey', 'governance', 'in_force', '2025-01-01'::date, 'Jersey', 'https://www.carrotsandsticks.org/policies/203_1', ARRAY['sdg9', 'mandatory', 'jersey', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf9366a9-6b26-573c-a2bf-5490f0dcc22c', 'Multinational Corporate Income Tax (Jersey) Law', 'Multinational Corporate Income Tax (Jersey) Law 2025', 'The Multinational Corporate Income Tax (Jersey) Law 2025 outlines taxation rules for large multinational enterprise groups in Jersey, covering definitions, chargeable groups, tax provisions, registration, returns, penalties, and appeals. Targeting multinational corporations operating in Jersey, it aims to regulate income tax responsibilities and procedures.', 'The Multinational Corporate Income Tax (Jersey) Law 2025 outlines taxation rules for large multinational enterprise groups in Jersey, covering definitions, chargeable groups, tax provisions, registration, returns, penalties, and appeals. Targeting multinational corporations operating in Jersey, it aims to regulate income tax responsibilities and procedures.', 'The Multinational Corporate Income Tax (Jersey) Law 2025 outlines taxation rules for large multinational enterprise groups in Jersey, covering definitions, chargeable groups, tax provisions, registration, returns, penalties, and appeals. Targeting multinational corporations operating in Jersey, it aims to regulate income tax responsibilities and procedures.', 'Jersey', 'governance', 'in_force', '2025-01-01'::date, 'Jersey', 'https://www.carrotsandsticks.org/policies/203_2', ARRAY['mandatory', 'jersey', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a90b33f6-034e-58ec-a4bc-ff090163f09e', 'Jordanian National Action Plan (JONAP) for the implementation', 'Jordanian National Action Plan (JONAP) for the implementation of UN Security Council resolution 1325 on Women, Peace and Security (2018-2021)', 'The (2018-2021) Jordanian National Action Plan (JONAP) for advancing the implementation of UN Security Council resolution 1325 on Women, Peace and Security (UNSCR 1325), and its subsequent resolutions, was developed to respond to the country’s latest security and military challenges. It is in line with Jordan’s commitments to promote and respect human rights, justice, equality and participation.', 'The (2018-2021) Jordanian National Action Plan (JONAP) for advancing the implementation of UN Security Council resolution 1325 on Women, Peace and Security (UNSCR 1325), and its subsequent resolutions, was developed to respond to the country’s latest security and military challenges. It is in line with Jordan’s commitments to promote and respect human rights, justice, equality and participation.', 'The (2018-2021) Jordanian National Action Plan (JONAP) for advancing the implementation of UN Security Council resolution 1325 on Women, Peace and Security (UNSCR 1325), and its subsequent resolutions, was developed to respond to the country’s latest security and military challenges. It is in line with Jordan’s commitments to promote and respect human rights, justice, equality and participation.', 'Jordan', 'social', 'in_force', '2018-01-01'::date, 'Jordan', 'https://www.carrotsandsticks.org/policies/88_2', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg5', 'sdg16', 'jordan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e2e7fc7c-fa05-5d31-90c0-78c9d3e1bed8', 'Jordan Sustainability 2', 'Sustainability 2', 'This brochure includes most important information related to sustainability reports from the aspect of its importance, its forms and the main principle for sustainability reporting, as well as the most important topics to be indicated in the sustainability report.', 'This brochure includes most important information related to sustainability reports from the aspect of its importance, its forms and the main principle for sustainability reporting, as well as the most important topics to be indicated in the sustainability report.', 'This brochure includes most important information related to sustainability reports from the aspect of its importance, its forms and the main principle for sustainability reporting, as well as the most important topics to be indicated in the sustainability report.', 'Jordan', 'climate', 'in_force', '2018-01-01'::date, 'Jordan', 'https://www.carrotsandsticks.org/policies/88_3', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg7', 'mandatory', 'sdg9', 'jordan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('10659f62-51cf-53dc-9895-39a52800dc98', 'Jordan Sustainability Reporting', 'Guidance on Sustainability Reporting 2018', 'This guide has been prepared to guide ASE listed companies to report on sustainability information, and inform on specific voluntary ESG disclosure requirements.', 'This guide has been prepared to guide ASE listed companies to report on sustainability information, and inform on specific voluntary ESG disclosure requirements.', 'This guide has been prepared to guide ASE listed companies to report on sustainability information, and inform on specific voluntary ESG disclosure requirements.', 'Jordan', 'climate', 'in_force', '2018-01-01'::date, 'Jordan', 'https://www.carrotsandsticks.org/policies/88_4', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'mandatory', 'sdg16', 'sdg12', 'jordan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0498cec5-2720-52a1-bfbb-5db36f351b11', 'Jordan Comprehensive National Plan for Human Rights', 'Comprehensive National Plan for Human Rights (2016-2025)', 'This plan was prepared after an in-depth study of the situation of human rights in the Kingdom, in order to address the existing deficiencies at the level of the legislations, policies and practices for promoting the situation of human rights and upgrading them in line with the national constants and the Kingdom’s constitution and according to the Kingdom’s commitment in this respect.', 'This plan was prepared after an in-depth study of the situation of human rights in the Kingdom, in order to address the existing deficiencies at the level of the legislations, policies and practices for promoting the situation of human rights and upgrading them in line with the national constants and the Kingdom’s constitution and according to the Kingdom’s commitment in this respect.', 'This plan was prepared after an in-depth study of the situation of human rights in the Kingdom, in order to address the existing deficiencies at the level of the legislations, policies and practices for promoting the situation of human rights and upgrading them in line with the national constants and the Kingdom’s constitution and according to the Kingdom’s commitment in this respect.', 'Jordan', 'nature', 'in_force', '2016-01-01'::date, 'Jordan', 'https://www.carrotsandsticks.org/policies/88_1', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg15', 'jordan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('59ad5fea-0b65-52f3-88b6-8a7a0876feb7', 'Jordanian Corporate Governance Code', 'Jordanian Corporate Governance Code 2011', 'The main objective of this Code is to provide guidelines to all kinds of organizations with the main purpose of increasing the vlaue of organizations; improving sustainability and performance of organizations and facilitating increased access to finance at lower costs.', 'The main objective of this Code is to provide guidelines to all kinds of organizations with the main purpose of increasing the vlaue of organizations; improving sustainability and performance of organizations and facilitating increased access to finance at lower costs.', 'The main objective of this Code is to provide guidelines to all kinds of organizations with the main purpose of increasing the vlaue of organizations; improving sustainability and performance of organizations and facilitating increased access to finance at lower costs.', 'Jordan', 'governance', 'in_force', '2011-01-01'::date, 'Jordan', 'https://www.carrotsandsticks.org/policies/88_7', ARRAY['guidance_frameworks', 'mandatory', 'sdg16', 'disclosure', 'jordan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c06b58d5-9a6e-56de-aa96-fa5cc3e571ab', 'Corporate Governance Code for Banks in Jordan', 'Corporate Governance Code for Banks in Jordan 2007', 'This Corporate Governance Code which is intended to promote international best practice in the corporate governance of Jordanian banks.', 'This Corporate Governance Code which is intended to promote international best practice in the corporate governance of Jordanian banks.', 'This Corporate Governance Code which is intended to promote international best practice in the corporate governance of Jordanian banks.', 'Jordan', 'governance', 'in_force', '2007-01-01'::date, 'Jordan', 'https://www.carrotsandsticks.org/policies/88_5', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'jordan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('da2bffc4-4c08-596c-b687-6e9edebf885a', 'Jordan Corporate Governance Code for Shareholding Companies Listed', 'Corporate Governance Code for Shareholding Companies Listed on the Amman Stock Exchange 2007', 'This guide was prepared in view of the development of the national economy at all levels, and in line with the Jordan Securities Commission (JSC)’s efforts to develop the national capital market and its regulatory and organizational framework. It contains rules of corporate governance for shareholding companies listed at Amman Stock Exchange (ASE) for the purpose of establishing a clear framework that regulates their relations and management and defines their rights, duties and responsibilities in order to realize their objectives and safeguard the rights of all stakeholders.', 'This guide was prepared in view of the development of the national economy at all levels, and in line with the Jordan Securities Commission (JSC)’s efforts to develop the national capital market and its regulatory and organizational framework. It contains rules of corporate governance for shareholding companies listed at Amman Stock Exchange (ASE) for the purpose of establishing a clear framework that regulates their relations and management and defines their rights, duties and responsibilities in order to realize their objectives and safeguard the rights of all stakeholders.', 'This guide was prepared in view of the development of the national economy at all levels, and in line with the Jordan Securities Commission (JSC)’s efforts to develop the national capital market and its regulatory and organizational framework. It contains rules of corporate governance for shareholding companies listed at Amman Stock Exchange (ASE) for the purpose of establishing a clear framework that regulates their relations and management and defines their rights, duties and responsibilities in order to realize their objectives and safeguard the rights of all stakeholders.', 'Jordan', 'governance', 'in_force', '2007-01-01'::date, 'Jordan', 'https://www.carrotsandsticks.org/policies/88_6', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'jordan']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('702d4d37-9f46-5bfc-97a0-2823bbe9c879', 'Kazakhstan Business Code', 'Business Code of the Republic of Kazakhstan', 'The Entrepreneurial Code outlines the relationships between the State, regulators and business entities. The in-depth Code covers the full lifespan of a business entity and details how the State, regulatory authorities and individual business entities should act with regard to, for example, debt and bankruptcy, social and environmental responsibility, monopoly, tariffs and state support, competition.', 'The Entrepreneurial Code outlines the relationships between the State, regulators and business entities. The in-depth Code covers the full lifespan of a business entity and details how the State, regulatory authorities and individual business entities should act with regard to, for example, debt and bankruptcy, social and environmental responsibility, monopoly, tariffs and state support, competition.', 'The Entrepreneurial Code outlines the relationships between the State, regulators and business entities. The in-depth Code covers the full lifespan of a business entity and details how the State, regulatory authorities and individual business entities should act with regard to, for example, debt and bankruptcy, social and environmental responsibility, monopoly, tariffs and state support, competition.', 'Kazakhstan', 'climate', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_12', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'sdg17', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1b0c4fc4-7595-5dd9-b834-8f11b14d7c68', 'Kazakhstan Civil Code', 'Civil Code of the Republic of Kazakhstan', 'The Civil Code regulates property relations, with a basis of the inviolability of property, in Kazakhstan, and is applicable to citizens, legal entities, the state, and administrative-territorial units. As such, the Code regulates key aspects to the founding and functioning of businesses in Kazakhstan. The Code determines how all business entities should act with regards to foundation, organization of capital, partnership and securities, liquidation, and bankruptcy, for example. These regulations are presented in general for all business and then in detail for different types of entity, e.g. partnership, limited liability, joint stock or cooperative.', 'The Civil Code regulates property relations, with a basis of the inviolability of property, in Kazakhstan, and is applicable to citizens, legal entities, the state, and administrative-territorial units. As such, the Code regulates key aspects to the founding and functioning of businesses in Kazakhstan. The Code determines how all business entities should act with regards to foundation, organization of capital, partnership and securities, liquidation, and bankruptcy, for example. These regulations are presented in general for all business and then in detail for different types of entity, e.g. partnership, limited liability, joint stock or cooperative.', 'The Civil Code regulates property relations, with a basis of the inviolability of property, in Kazakhstan, and is applicable to citizens, legal entities, the state, and administrative-territorial units. As such, the Code regulates key aspects to the founding and functioning of businesses in Kazakhstan. The Code determines how all business entities should act with regards to foundation, organization of capital, partnership and securities, liquidation, and bankruptcy, for example. These regulations are presented in general for all business and then in detail for different types of entity, e.g. partnership, limited liability, joint stock or cooperative.', 'Kazakhstan', 'circularity', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_13', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'sdg17', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('189bb2b8-320e-57ac-9f33-666b25d5f4a3', 'Kazakhstan Accounting and Financial Reporting', 'Law on Accounting and Financial Reporting', 'This Act regulates the system of accounting and financial reporting in Kazakhstan and establishes the principles, qualitive characteristics and rules of accounting and financial reporting. Article 2 of the Law lists the types of organization that are required to produce annual accounting and financial reports. Further detailed in the Law are practicalities, contents and requirements of both accounting and financial reports, with emphasis put on the different actors involved in the reporting process.', 'This Act regulates the system of accounting and financial reporting in Kazakhstan and establishes the principles, qualitive characteristics and rules of accounting and financial reporting. Article 2 of the Law lists the types of organization that are required to produce annual accounting and financial reports. Further detailed in the Law are practicalities, contents and requirements of both accounting and financial reports, with emphasis put on the different actors involved in the reporting process.', 'This Act regulates the system of accounting and financial reporting in Kazakhstan and establishes the principles, qualitive characteristics and rules of accounting and financial reporting. Article 2 of the Law lists the types of organization that are required to produce annual accounting and financial reports. Further detailed in the Law are practicalities, contents and requirements of both accounting and financial reports, with emphasis put on the different actors involved in the reporting process.', 'Kazakhstan', 'climate', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_14', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ea43d8a6-c375-5658-a902-e5c232f56403', 'Kazakhstan Law dated November 20, 1998 I On Auditing', 'Law of the Republic of Kazakhstan dated November 20, 1998 No. 304-I On Auditing Activities', 'The Law on Auditing determines and regulates the relationship between public authorities, individuals, legal entities, auditors and audit organizations in audit activity. The Law determines which companies and organizations are subject to obligatory audit and details how these entities should act in relation to the audit. The Law also regulates the practicalities of the audit for those conducting it, determining what should be examined and produced.', 'The Law on Auditing determines and regulates the relationship between public authorities, individuals, legal entities, auditors and audit organizations in audit activity. The Law determines which companies and organizations are subject to obligatory audit and details how these entities should act in relation to the audit. The Law also regulates the practicalities of the audit for those conducting it, determining what should be examined and produced.', 'The Law on Auditing determines and regulates the relationship between public authorities, individuals, legal entities, auditors and audit organizations in audit activity. The Law determines which companies and organizations are subject to obligatory audit and details how these entities should act in relation to the audit. The Law also regulates the practicalities of the audit for those conducting it, determining what should be examined and produced.', 'Kazakhstan', 'climate', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_15', ARRAY['kazakhstan', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('87c4f37c-14bf-5dc3-bb75-11988f99d66f', 'Kazakhstan Law dated July 9, 2004 II on Electric', 'Law of the Republic of Kazakhstan dated July 9, 2004 No. 588-II on Electric Power', 'This Law regulates the processes of production, transmission and consumption of electricity and heat, outlining the obligations of those companies who produce and transmit energy in Kazakhstan. In terms of reporting, Article 12 requires those energy companies that do not use renewable energy sources to submit an annual report to the authorized body. This report is to contain the annual information on the costs and sizes of production and sales of electric energy, and is to be submitted no later than 31 March the following year.', 'This Law regulates the processes of production, transmission and consumption of electricity and heat, outlining the obligations of those companies who produce and transmit energy in Kazakhstan. In terms of reporting, Article 12 requires those energy companies that do not use renewable energy sources to submit an annual report to the authorized body. This report is to contain the annual information on the costs and sizes of production and sales of electric energy, and is to be submitted no later than 31 March the following year.', 'This Law regulates the processes of production, transmission and consumption of electricity and heat, outlining the obligations of those companies who produce and transmit energy in Kazakhstan. In terms of reporting, Article 12 requires those energy companies that do not use renewable energy sources to submit an annual report to the authorized body. This report is to contain the annual information on the costs and sizes of production and sales of electric energy, and is to be submitted no later than 31 March the following year.', 'Kazakhstan', 'climate', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_17', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'sdg7', 'mandatory', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('148ad8fa-834e-5ca6-b788-66ab64072ffc', 'Kazakhstan Law dated May 13, 2003 II On joint-stock', 'Law of the Republic of Kazakhstan dated May 13, 2003 No. 415-II On joint-stock companies', 'The Law on Joint Stock Companies provides the framework that joint stock companies must abide by and so acts as a management resource for these companies. The Law covers all aspects of the formation, running and sale of joint stock companies, paying special attention to stockholder rights and their obligations to the company. Chapter 5 of the Law is dedicated to company management and so provides the basis for the governance rules that those involved in the management and governance of joint stock companies must follow.', 'The Law on Joint Stock Companies provides the framework that joint stock companies must abide by and so acts as a management resource for these companies. The Law covers all aspects of the formation, running and sale of joint stock companies, paying special attention to stockholder rights and their obligations to the company. Chapter 5 of the Law is dedicated to company management and so provides the basis for the governance rules that those involved in the management and governance of joint stock companies must follow.', 'The Law on Joint Stock Companies provides the framework that joint stock companies must abide by and so acts as a management resource for these companies. The Law covers all aspects of the formation, running and sale of joint stock companies, paying special attention to stockholder rights and their obligations to the company. Chapter 5 of the Law is dedicated to company management and so provides the basis for the governance rules that those involved in the management and governance of joint stock companies must follow.', 'Kazakhstan', 'governance', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_19', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('08f73c3f-be56-59aa-837f-8329ca047e32', 'Kazakhstan Law About Supporting the Use of Renewable Energy', 'Law of the Republic of Kazakhstan About Supporting the Use of Renewable Energy Sources', 'The Law on Supporting the Use of Renewable Energy Sources provides the objectives, forms and directions of support for the promotion of renewable energy sources in Kazakhstan. The Law requires that the State creates favorable conditions for the uptake of renewable energy production and transmission. As such, Article 7-1 requires those companies that produce of renewable energy and the transmission companies that connect to renewable sources to submit monthly and annual reports on actual and expected output for the previous and future period to the Settlement and Financial Center. The Law specifies the dates and timings of said submissions.', 'The Law on Supporting the Use of Renewable Energy Sources provides the objectives, forms and directions of support for the promotion of renewable energy sources in Kazakhstan. The Law requires that the State creates favorable conditions for the uptake of renewable energy production and transmission. As such, Article 7-1 requires those companies that produce of renewable energy and the transmission companies that connect to renewable sources to submit monthly and annual reports on actual and expected output for the previous and future period to the Settlement and Financial Center. The Law specifies the dates and timings of said submissions.', 'The Law on Supporting the Use of Renewable Energy Sources provides the objectives, forms and directions of support for the promotion of renewable energy sources in Kazakhstan. The Law requires that the State creates favorable conditions for the uptake of renewable energy production and transmission. As such, Article 7-1 requires those companies that produce of renewable energy and the transmission companies that connect to renewable sources to submit monthly and annual reports on actual and expected output for the previous and future period to the Settlement and Financial Center. The Law specifies the dates and timings of said submissions.', 'Kazakhstan', 'climate', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_20', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'sdg7', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('600beb31-a89d-5113-b178-a7ef8eb81928', 'Kazakhstan Water Code', 'Water Code of the Republic of Kazakhstan', 'The objectives of water legislation of the Republic of Kazakhstan are the regulation of water relations of the purpose of rational and sustainable water use.', 'The objectives of water legislation of the Republic of Kazakhstan are the regulation of water relations of the purpose of rational and sustainable water use.', 'The objectives of water legislation of the Republic of Kazakhstan are the regulation of water relations of the purpose of rational and sustainable water use.', 'Kazakhstan', 'nature', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_21', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'kazakhstan', 'mandatory', 'sdg6', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d58b947e-22e6-5aab-9b9f-e6b0b69261bc', 'Kazakhstan Classification (taxonomy) of the "green" projects which are', 'Classification (taxonomy) of the "green" projects which are subject to financing through "green" bonds and the "green" credits', 'This Classification (taxonomy) is developed according to Item 3 of article 130 of the Ecological code of the Republic of Kazakhstan of January 2, 2021 and represents classification system of categories of the "green" projects (including quantitative and high-quality threshold values) directed to increase in efficiency of use of the existing natural resources, decrease in level of negative impact on the environment, increase in energy efficiency, energy saving, mitigation of the consequences of climate change and adaptation to climate change, given in appendix to this taxonomy.', 'This Classification (taxonomy) is developed according to Item 3 of article 130 of the Ecological code of the Republic of Kazakhstan of January 2, 2021 and represents classification system of categories of the "green" projects (including quantitative and high-quality threshold values) directed to increase in efficiency of use of the existing natural resources, decrease in level of negative impact on the environment, increase in energy efficiency, energy saving, mitigation of the consequences of climate change and adaptation to climate change, given in appendix to this taxonomy.', 'This Classification (taxonomy) is developed according to Item 3 of article 130 of the Ecological code of the Republic of Kazakhstan of January 2, 2021 and represents classification system of categories of the "green" projects (including quantitative and high-quality threshold values) directed to increase in efficiency of use of the existing natural resources, decrease in level of negative impact on the environment, increase in energy efficiency, energy saving, mitigation of the consequences of climate change and adaptation to climate change, given in appendix to this taxonomy.', 'Kazakhstan', 'climate', 'in_force', '2022-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_25', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'kazakhstan', 'sdg7', 'mandatory', 'sdg6', 'mandatory_regulations', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42b92623-e1f4-52b4-b162-2bb2a39d83fc', 'Kazakhstan Labor Code', 'Labor Code of the Republic of Kazakhstan', 'The Labor Code regulates the requirements and relationship between employers and employees. The Code covers, for example, working hours, minimum wages, holiday and sickness entitlement, contractual arrangements etc. The fields of health and safety require reporting from the employer. Article 182 requires employers to report to the local authority the results of facility certification, which are required for various industrial working environments (further detailed in Article 183), within one month of award. In addition, in case of workplace accidents that cause death or disability, employers must, according to Article 187, submit a report to the local authority and the territorial division in charge of work health and safety, the representative of the workers, insurance company, and law enforcement an initial report of the accident, including an photo of the scene, with the use of the referenced form.', 'The Labor Code regulates the requirements and relationship between employers and employees. The Code covers, for example, working hours, minimum wages, holiday and sickness entitlement, contractual arrangements etc. The fields of health and safety require reporting from the employer. Article 182 requires employers to report to the local authority the results of facility certification, which are required for various industrial working environments (further detailed in Article 183), within one month of award. In addition, in case of workplace accidents that cause death or disability, employers must, according to Article 187, submit a report to the local authority and the territorial division in charge of work health and safety, the representative of the workers, insurance company, and law enforcement an initial report of the accident, including an photo of the scene, with the use of the referenced form.', 'The Labor Code regulates the requirements and relationship between employers and employees. The Code covers, for example, working hours, minimum wages, holiday and sickness entitlement, contractual arrangements etc. The fields of health and safety require reporting from the employer. Article 182 requires employers to report to the local authority the results of facility certification, which are required for various industrial working environments (further detailed in Article 183), within one month of award. In addition, in case of workplace accidents that cause death or disability, employers must, according to Article 187, submit a report to the local authority and the territorial division in charge of work health and safety, the representative of the workers, insurance company, and law enforcement an initial report of the accident, including an photo of the scene, with the use of the referenced form.', 'Kazakhstan', 'climate', 'in_force', '2021-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_10', ARRAY['sdg4', 'sdg8', 'other sustainability policy', 'regulations', 'kazakhstan', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d069129d-329f-52d8-97ef-5a320f22ce05', 'Kazakhstan Law On Civil Protection', 'Law of the Republic of Kazakhstan On Civil Protection', 'The Law on Civil Protection details the regulations in place to protect the public and environment by preventing and reducing the effects of natural or man-made emergencies, which, in terms of reporting, relates to industrial safety. Articles 74 and 75 requires those entities that use technologies, devices or materials of hazardous of explosive potential to apply for permits to operate, the details of which are outlined in the two Articles. Additionally, Article 82 of the Law on Civil Protection details the requirements of the organizations that operate the potentially hazardous facilities in case of incident or accident, which includes the immediate reporting of information concerning the situation to local authorities.', 'The Law on Civil Protection details the regulations in place to protect the public and environment by preventing and reducing the effects of natural or man-made emergencies, which, in terms of reporting, relates to industrial safety. Articles 74 and 75 requires those entities that use technologies, devices or materials of hazardous of explosive potential to apply for permits to operate, the details of which are outlined in the two Articles. Additionally, Article 82 of the Law on Civil Protection details the requirements of the organizations that operate the potentially hazardous facilities in case of incident or accident, which includes the immediate reporting of information concerning the situation to local authorities.', 'The Law on Civil Protection details the regulations in place to protect the public and environment by preventing and reducing the effects of natural or man-made emergencies, which, in terms of reporting, relates to industrial safety. Articles 74 and 75 requires those entities that use technologies, devices or materials of hazardous of explosive potential to apply for permits to operate, the details of which are outlined in the two Articles. Additionally, Article 82 of the Law on Civil Protection details the requirements of the organizations that operate the potentially hazardous facilities in case of incident or accident, which includes the immediate reporting of information concerning the situation to local authorities.', 'Kazakhstan', 'climate', 'in_force', '2021-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_16', ARRAY['kazakhstan', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a97735b2-bf6f-5815-81a2-e279f15c57a2', 'Kazakhstan Astana International Exchange’s voluntary disclosure guidance for environmental', 'Astana International Exchange’s voluntary disclosure guidance for environmental, social and governance (esg) reporting', 'The Amman Stock Exchange (AIX) has released guidance for ESG reporting for listed companies, funds, asset managers, and issuers of debentures and securities. The guidance encourages reporting on ESG aspects and aims to shift to a "comply-or-explain" principle starting in 2024 and introduce mandatory ESG reporting in 2026. The guidance also identifies the importance of ESG reporting for funds and fund managers and encourages disclosure of ESG aspects for companies that have issued green and social bonds. The guidance references several frameworks, including GRI, SASB, TCFD, CDSB, and International Integrated Reporting Council.', 'The Amman Stock Exchange (AIX) has released guidance for ESG reporting for listed companies, funds, asset managers, and issuers of debentures and securities. The guidance encourages reporting on ESG aspects and aims to shift to a "comply-or-explain" principle starting in 2024 and introduce mandatory ESG reporting in 2026. The guidance also identifies the importance of ESG reporting for funds and fund managers and encourages disclosure of ESG aspects for companies that have issued green and social bonds. The guidance references several frameworks, including GRI, SASB, TCFD, CDSB, and International Integrated Reporting Council.', 'The Amman Stock Exchange (AIX) has released guidance for ESG reporting for listed companies, funds, asset managers, and issuers of debentures and securities. The guidance encourages reporting on ESG aspects and aims to shift to a "comply-or-explain" principle starting in 2024 and introduce mandatory ESG reporting in 2026. The guidance also identifies the importance of ESG reporting for funds and fund managers and encourages disclosure of ESG aspects for companies that have issued green and social bonds. The guidance references several frameworks, including GRI, SASB, TCFD, CDSB, and International Integrated Reporting Council.', 'Kazakhstan', 'climate', 'in_force', '2021-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_23', ARRAY['guidance_frameworks', 'kazakhstan', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('89cd886b-dd8a-5066-9131-49ed292b5fa2', 'Kazakhstan Environmental Code (Code VI ZRK of', 'Environmental Code of the Republic of Kazakhstan (Code No. 400-VI ZRK of 2021)', 'This Code regulates public relations in the field of human and nature interaction (the environmental relations) that arise from activities of individuals and legal entities that have or may have a negative impact on the environment. The Code also regulates public relations in monitoring the state of the environment and meteorological and hydrological monitoring that are aimed to meet the needs of the State, individuals and legal entities for environmental and hydrometeorological information.', 'This Code regulates public relations in the field of human and nature interaction (the environmental relations) that arise from activities of individuals and legal entities that have or may have a negative impact on the environment. The Code also regulates public relations in monitoring the state of the environment and meteorological and hydrological monitoring that are aimed to meet the needs of the State, individuals and legal entities for environmental and hydrometeorological information.', 'This Code regulates public relations in the field of human and nature interaction (the environmental relations) that arise from activities of individuals and legal entities that have or may have a negative impact on the environment. The Code also regulates public relations in monitoring the state of the environment and meteorological and hydrological monitoring that are aimed to meet the needs of the State, individuals and legal entities for environmental and hydrometeorological information.', 'Kazakhstan', 'climate', 'in_force', '2021-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_24', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'kazakhstan', 'sdg7', 'mandatory', 'sdg16', 'sdg12', 'sdg15', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9708c239-30d3-5515-a138-76431ee78192', 'Kazakhstan Environmental Code', 'Environmental Code of the Republic of Kazakhstan', 'In January 2021, the Republic of Kazakhstan adopted a New Environmental Code which includes (among other new features) policy to support the introduction of the best available techniques (BAT). This Code regulates activities of individuals and legal entities that have or may have a negative impact on the environment.', 'In January 2021, the Republic of Kazakhstan adopted a New Environmental Code which includes (among other new features) policy to support the introduction of the best available techniques (BAT). This Code regulates activities of individuals and legal entities that have or may have a negative impact on the environment.', 'In January 2021, the Republic of Kazakhstan adopted a New Environmental Code which includes (among other new features) policy to support the introduction of the best available techniques (BAT). This Code regulates activities of individuals and legal entities that have or may have a negative impact on the environment.', 'Kazakhstan', 'climate', 'in_force', '2021-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_8', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aff0d92e-f013-5f34-ae56-fc470a7137f0', 'Kazakhstan Law On Energy Saving and Energy Efficiency', 'Law of the Republic of Kazakhstan On Energy Saving and Energy Efficiency', 'This Law determines the legal, economic and organizational basis for activities in the field of energy conservation and efficiency, with regulations that affect the state, local authorities and companies. Article 9 of the Law is related to the functioning of a State Energy Register. This platform/database would compile the submissions made from those subject to the Register. The Article outlines the information that shall be submitted by the companies, which includes business context, energy and water use, action plan for conservation and efficiency and results of execution of action plan.', 'This Law determines the legal, economic and organizational basis for activities in the field of energy conservation and efficiency, with regulations that affect the state, local authorities and companies. Article 9 of the Law is related to the functioning of a State Energy Register. This platform/database would compile the submissions made from those subject to the Register. The Article outlines the information that shall be submitted by the companies, which includes business context, energy and water use, action plan for conservation and efficiency and results of execution of action plan.', 'This Law determines the legal, economic and organizational basis for activities in the field of energy conservation and efficiency, with regulations that affect the state, local authorities and companies. Article 9 of the Law is related to the functioning of a State Energy Register. This platform/database would compile the submissions made from those subject to the Register. The Article outlines the information that shall be submitted by the companies, which includes business context, energy and water use, action plan for conservation and efficiency and results of execution of action plan.', 'Kazakhstan', 'climate', 'in_force', '2020-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_18', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'sdg7', 'mandatory', 'sdg6', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('90079e2a-09d2-5736-b9cf-461a9d4fed4c', 'Kazakhstan Methodology of preparing an Environmental, Social and Governance', 'Methodology of preparing an Environmental, Social and Governance report 2018', 'The Methodology provides guidance on how to prepare an Environmental, Social and Governance Report (hereinafter the “ESG Report”) which aims at assisting in the formation of appropriate corporate governance and risk management systems in companies, improving the investment climate in Kazakhstan, including enhancing the attractiveness of companies for foreign investors, ensuring long-term sustainable investment and raising the level of disclosure. In addition, the use of this Methodology will also contribute to implementation of the UN Sustainable Development Goals in the Republic of Kazakhstan.', 'The Methodology provides guidance on how to prepare an Environmental, Social and Governance Report (hereinafter the “ESG Report”) which aims at assisting in the formation of appropriate corporate governance and risk management systems in companies, improving the investment climate in Kazakhstan, including enhancing the attractiveness of companies for foreign investors, ensuring long-term sustainable investment and raising the level of disclosure. In addition, the use of this Methodology will also contribute to implementation of the UN Sustainable Development Goals in the Republic of Kazakhstan.', 'The Methodology provides guidance on how to prepare an Environmental, Social and Governance Report (hereinafter the “ESG Report”) which aims at assisting in the formation of appropriate corporate governance and risk management systems in companies, improving the investment climate in Kazakhstan, including enhancing the attractiveness of companies for foreign investors, ensuring long-term sustainable investment and raising the level of disclosure. In addition, the use of this Methodology will also contribute to implementation of the UN Sustainable Development Goals in the Republic of Kazakhstan.', 'Kazakhstan', 'climate', 'in_force', '2018-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_6', ARRAY['sdg13', 'kazakhstan', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('850ee33f-d020-5037-8b0d-9380cb8a9186', 'Kazakhstan strategy of ensuring regional leadership of the AIFC', 'The strategy of ensuring regional leadership of the AIFC in the sphere of green finance until the year 2025', 'In accordance with the 2030 Agenda for Sustainable Development based on the UN Sustainable Development Goals (SDG), the Republic of Kazakhstan aims to achieve a just, rights-based, equitable and inclusive world. Well-timed steps taken on the introduction of elements of sustainable development into the strategic plans for the development of the Republic will allow Kazakhstan to enter a new stage of forming a sustainable future and become a leader in the region. Taking into account the created favorable conditions and the geographic position of Kazakhstan, the AIFC should become a regional hub of green finance promoting the development and management of green financing instruments in the Central Asian and Eastern European region, linking the best world practices of the West and the East.', 'In accordance with the 2030 Agenda for Sustainable Development based on the UN Sustainable Development Goals (SDG), the Republic of Kazakhstan aims to achieve a just, rights-based, equitable and inclusive world. Well-timed steps taken on the introduction of elements of sustainable development into the strategic plans for the development of the Republic will allow Kazakhstan to enter a new stage of forming a sustainable future and become a leader in the region. Taking into account the created favorable conditions and the geographic position of Kazakhstan, the AIFC should become a regional hub of green finance promoting the development and management of green financing instruments in the Central Asian and Eastern European region, linking the best world practices of the West and the East.', 'In accordance with the 2030 Agenda for Sustainable Development based on the UN Sustainable Development Goals (SDG), the Republic of Kazakhstan aims to achieve a just, rights-based, equitable and inclusive world. Well-timed steps taken on the introduction of elements of sustainable development into the strategic plans for the development of the Republic will allow Kazakhstan to enter a new stage of forming a sustainable future and become a leader in the region. Taking into account the created favorable conditions and the geographic position of Kazakhstan, the AIFC should become a regional hub of green finance promoting the development and management of green financing instruments in the Central Asian and Eastern European region, linking the best world practices of the West and the East.', 'Kazakhstan', 'climate', 'in_force', '2017-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_22', ARRAY['kazakhstan', 'sdg7', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('03c728e6-f834-5aac-839a-d4181a9d6afd', 'Kazakhstan Concept on introduction and development of green finance', 'Concept on introduction and development of green finance instruments and principles', 'This project was established to assist the AIFC scope, conceptualize and initiate development of a domestic green financial system. Given its unique regulatory status, strong mandate for green finance development and the high political priority on achieving success, the AIFC is well placed to play a central, coordinating role.', 'This project was established to assist the AIFC scope, conceptualize and initiate development of a domestic green financial system. Given its unique regulatory status, strong mandate for green finance development and the high political priority on achieving success, the AIFC is well placed to play a central, coordinating role.', 'This project was established to assist the AIFC scope, conceptualize and initiate development of a domestic green financial system. Given its unique regulatory status, strong mandate for green finance development and the high political priority on achieving success, the AIFC is well placed to play a central, coordinating role.', 'Kazakhstan', 'climate', 'in_force', '2017-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_7', ARRAY['guidance_frameworks', 'sdg13', 'kazakhstan', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('913cf5f5-9dd5-5acd-b1a5-41b0a3897405', 'Kazakhstan Methodology of preparing an ESG Report', 'Methodology of preparing an ESG Report 2016', 'This Methodology of preparing an Environmental, Social and Governance report (hereinafter – the ESG report) was developed as part of the move of Kazakhstan Stock Exchange JSC (hereinafter – the Exchange) to join the UN initiative called "Sustainable Stock Exchanges", promoting the cooperation between exchanges, investors and regulators for purposes of facilitating the long-term sustainable investing, increasing the level of information disclosure and is designed for listed companies, irrespective of their size, industry or location.', 'This Methodology of preparing an Environmental, Social and Governance report (hereinafter – the ESG report) was developed as part of the move of Kazakhstan Stock Exchange JSC (hereinafter – the Exchange) to join the UN initiative called "Sustainable Stock Exchanges", promoting the cooperation between exchanges, investors and regulators for purposes of facilitating the long-term sustainable investing, increasing the level of information disclosure and is designed for listed companies, irrespective of their size, industry or location.', 'This Methodology of preparing an Environmental, Social and Governance report (hereinafter – the ESG report) was developed as part of the move of Kazakhstan Stock Exchange JSC (hereinafter – the Exchange) to join the UN initiative called "Sustainable Stock Exchanges", promoting the cooperation between exchanges, investors and regulators for purposes of facilitating the long-term sustainable investing, increasing the level of information disclosure and is designed for listed companies, irrespective of their size, industry or location.', 'Kazakhstan', 'climate', 'in_force', '2016-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_5', ARRAY['kazakhstan', 'sdg17', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6dc733aa-2822-52dc-9bd4-0a911aa83097', 'Kazakhstan Corporate governance code of the sovereign wealth fund', 'Corporate governance code of the sovereign wealth fund Samruk-Kazyna', 'The goals of the Code are to improve the corporate governance of the Fund and the Organisations, provide for governance transparency, and confirm the Fund and the Organisations’ commitment to adhere to standards of good corporate governance. The Code consists of two parts: the Principles and the Annotations, the latter being rules and clarifications for implementing the Principles.', 'The goals of the Code are to improve the corporate governance of the Fund and the Organisations, provide for governance transparency, and confirm the Fund and the Organisations’ commitment to adhere to standards of good corporate governance. The Code consists of two parts: the Principles and the Annotations, the latter being rules and clarifications for implementing the Principles.', 'The goals of the Code are to improve the corporate governance of the Fund and the Organisations, provide for governance transparency, and confirm the Fund and the Organisations’ commitment to adhere to standards of good corporate governance. The Code consists of two parts: the Principles and the Annotations, the latter being rules and clarifications for implementing the Principles.', 'Kazakhstan', 'climate', 'in_force', '2015-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_2', ARRAY['kazakhstan', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3579bea1-e880-50dc-a77e-104e8913f77d', 'Kazakhstan Stock exchange listing requirements', 'Stock exchange listing requirements', 'The Stock Exchange Listing Requirements policy in Kazakhstan, effective from November 2009, outlines rules for companies seeking listing on the Kazakhstan Stock Exchange. The policy covers general provisions, listing requirements and procedures, and the structure of the official list. Amendments and additions have been made over the years to enhance regulatory compliance and market transparency. The policy aims to ensure companies meet specified criteria for listing and adhere to exchange obligations. It is a mandatory policy overseen by the Kazakhstan Stock Exchange and relevant regulatory agencies.', 'The Stock Exchange Listing Requirements policy in Kazakhstan, effective from November 2009, outlines rules for companies seeking listing on the Kazakhstan Stock Exchange. The policy covers general provisions, listing requirements and procedures, and the structure of the official list. Amendments and additions have been made over the years to enhance regulatory compliance and market transparency. The policy aims to ensure companies meet specified criteria for listing and adhere to exchange obligations. It is a mandatory policy overseen by the Kazakhstan Stock Exchange and relevant regulatory agencies.', 'The Stock Exchange Listing Requirements policy in Kazakhstan, effective from November 2009, outlines rules for companies seeking listing on the Kazakhstan Stock Exchange. The policy covers general provisions, listing requirements and procedures, and the structure of the official list. Amendments and additions have been made over the years to enhance regulatory compliance and market transparency. The policy aims to ensure companies meet specified criteria for listing and adhere to exchange obligations. It is a mandatory policy overseen by the Kazakhstan Stock Exchange and relevant regulatory agencies.', 'Kazakhstan', 'governance', 'in_force', '2009-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_3', ARRAY['guidance_frameworks', 'other sustainability policy', 'kazakhstan', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6d3f4dfa-b356-5304-a860-dd92dfa0fb34', 'Kazakhstan Corporate Governance', 'Code on Corporate Governance 2007', 'The present Code on Corporate Governance (hereinafter referred to as “the Code”) is a statute of rules and recommendations, which the Company follows in its activity for provision of high level of business ethics in relations within the Company and other market’s participants.', 'The present Code on Corporate Governance (hereinafter referred to as “the Code”) is a statute of rules and recommendations, which the Company follows in its activity for provision of high level of business ethics in relations within the Company and other market’s participants.', 'The present Code on Corporate Governance (hereinafter referred to as “the Code”) is a statute of rules and recommendations, which the Company follows in its activity for provision of high level of business ethics in relations within the Company and other market’s participants.', 'Kazakhstan', 'governance', 'in_force', '2007-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_1', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d9d695a2-5344-5856-b779-d60069e0950d', 'Kazakhstan On approval of the Instructions for conducting an', 'On approval of the Instructions for conducting an environmental impact assessment', 'Those conducting industrial environmental monitoring in accordance with the Environmental Code (Article 128), are required to prepare a report based on the results of the monitoring exercise. The report should appear on the form according to the appendix to this order.', 'Those conducting industrial environmental monitoring in accordance with the Environmental Code (Article 128), are required to prepare a report based on the results of the monitoring exercise. The report should appear on the form according to the appendix to this order.', 'Those conducting industrial environmental monitoring in accordance with the Environmental Code (Article 128), are required to prepare a report based on the results of the monitoring exercise. The report should appear on the form according to the appendix to this order.', 'Kazakhstan', 'climate', 'in_force', '2007-01-01'::date, 'Kazakhstan', 'https://www.carrotsandsticks.org/policies/89_11', ARRAY['other sustainability policy', 'regulations', 'kazakhstan', 'sdg11', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('83a54c33-26c7-5fb1-a2e3-767647568701', 'Kenya Nairobi Securities Exchange ESG Disclosures', 'Nairobi Securities Exchange ESG Disclosures', 'The focus of this document  is to illustrate and guide how listed companies in Kenya and other organisations interested in ESG reporting can collect, analyse, and publicly disclose important ESG information using an approach that meets international standards on sustainability reporting. This document can also act a guide on how to progressively integrate ESG in strategy, operations, and performance management.', 'The focus of this document  is to illustrate and guide how listed companies in Kenya and other organisations interested in ESG reporting can collect, analyse, and publicly disclose important ESG information using an approach that meets international standards on sustainability reporting. This document can also act a guide on how to progressively integrate ESG in strategy, operations, and performance management.', 'The focus of this document  is to illustrate and guide how listed companies in Kenya and other organisations interested in ESG reporting can collect, analyse, and publicly disclose important ESG information using an approach that meets international standards on sustainability reporting. This document can also act a guide on how to progressively integrate ESG in strategy, operations, and performance management.', 'Kenya', 'climate', 'in_force', '2021-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_24', ARRAY['sdg13', 'other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1542cf21-e2d6-5e35-99e1-5cee3b58c0c4', 'Kenya Capital Markets Act', 'The Capital Markets Act, 1989', 'An Act of Parliament to establish a Capital Markets Authority for the purpose of promoting, regulating and facilitating the capital markets in the country.', 'An Act of Parliament to establish a Capital Markets Authority for the purpose of promoting, regulating and facilitating the capital markets in the country.', 'An Act of Parliament to establish a Capital Markets Authority for the purpose of promoting, regulating and facilitating the capital markets in the country.', 'Kenya', 'governance', 'in_force', '2017-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_23', ARRAY['mandatory', 'other sustainability policy', 'kenya', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('51ed4c5b-9bb8-5d56-8c61-c1114b0958cb', 'Kenya Mining Act', 'The Mining Act, 2016', 'The Act greatly simplifies the types of mining rights that may be granted to investors as well as the acquisition process for such rights. Prospecting and mining rights will now be in the form of either a permit (for small scale operations) or a license (for large scale operations).', 'The Act greatly simplifies the types of mining rights that may be granted to investors as well as the acquisition process for such rights. Prospecting and mining rights will now be in the form of either a permit (for small scale operations) or a license (for large scale operations).', 'The Act greatly simplifies the types of mining rights that may be granted to investors as well as the acquisition process for such rights. Prospecting and mining rights will now be in the form of either a permit (for small scale operations) or a license (for large scale operations).', 'Kenya', 'climate', 'in_force', '2016-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_19', ARRAY['mandatory', 'other sustainability policy', 'kenya', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d7ad47cc-00a3-5b42-bba0-560d0f716fcd', 'Kenya Bribery Act', 'Bribery Act, 2016', 'This document is concerned with an Act of the Kenyan Parliament to provide for the prevention, investigation and punishment of bribery, and for connected purposes.', 'This document is concerned with an Act of the Kenyan Parliament to provide for the prevention, investigation and punishment of bribery, and for connected purposes.', 'This document is concerned with an Act of the Kenyan Parliament to provide for the prevention, investigation and punishment of bribery, and for connected purposes.', 'Kenya', 'governance', 'in_force', '2016-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_5', ARRAY['other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d0711c3e-6a11-53a1-aea5-14c826837f63', 'Kenya Capital Markets Act', 'The Capital Markets Act', 'This Code sets out the principles and specific recommendations on structures and processes, which companies should adopt in making good corporate governance an integral part of their business dealings and culture.', 'This Code sets out the principles and specific recommendations on structures and processes, which companies should adopt in making good corporate governance an integral part of their business dealings and culture.', 'This Code sets out the principles and specific recommendations on structures and processes, which companies should adopt in making good corporate governance an integral part of their business dealings and culture.', 'Kenya', 'governance', 'in_force', '2015-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_1', ARRAY['other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2e97b03a-6761-5244-9dbd-e168c7534d5a', 'Kenya Capital Markets Act', 'The Capital Markets Act', 'An Act of Parliament to establish a Capital Markets Authority for the purpose of promoting, regulating and facilitating the development of an orderly, fair and efficient Capital Markets in Kenya and for connected purpose.', 'An Act of Parliament to establish a Capital Markets Authority for the purpose of promoting, regulating and facilitating the development of an orderly, fair and efficient Capital Markets in Kenya and for connected purpose.', 'An Act of Parliament to establish a Capital Markets Authority for the purpose of promoting, regulating and facilitating the development of an orderly, fair and efficient Capital Markets in Kenya and for connected purpose.', 'Kenya', 'governance', 'in_force', '2015-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_7', ARRAY['mandatory', 'other sustainability policy', 'kenya', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1b68e965-bf8b-56ab-be3c-83f97112cd49', 'Kenya Companies Act', 'The Companies Act, 2015', 'This document outlines an Act of the Kenyan Parliament to consolidate and reform the law relating to the incorporation, registration, operation, management and regulation of companies; to provide for the appointment and functions of auditors; to make other provision relating to companies; and to provide for related matters.', 'This document outlines an Act of the Kenyan Parliament to consolidate and reform the law relating to the incorporation, registration, operation, management and regulation of companies; to provide for the appointment and functions of auditors; to make other provision relating to companies; and to provide for related matters.', 'This document outlines an Act of the Kenyan Parliament to consolidate and reform the law relating to the incorporation, registration, operation, management and regulation of companies; to provide for the appointment and functions of auditors; to make other provision relating to companies; and to provide for related matters.', 'Kenya', 'governance', 'in_force', '2015-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_8', ARRAY['other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ccdfc0d3-da86-5283-be9f-d19d25951e5b', 'Kenya E Environmental Management and Co-ordination Act ( of', 'E Environmental Management and Co-ordination Act (No 8 of 1999)', 'The Environmental Management and Co-ordination Act (No 8 of 1999) in Kenya focuses on regulating air quality through comprehensive provisions targeting air pollution control from both stationary and mobile sources. It establishes emission limits, control areas, occupational air quality limits, licensing requirements, measurement methods, reporting obligations, and penalties for non-compliance. The policy aims to protect human health, set standards for air quality, and ensure compliance with environmental regulations.', 'The Environmental Management and Co-ordination Act (No 8 of 1999) in Kenya focuses on regulating air quality through comprehensive provisions targeting air pollution control from both stationary and mobile sources. It establishes emission limits, control areas, occupational air quality limits, licensing requirements, measurement methods, reporting obligations, and penalties for non-compliance. The policy aims to protect human health, set standards for air quality, and ensure compliance with environmental regulations.', 'The Environmental Management and Co-ordination Act (No 8 of 1999) in Kenya focuses on regulating air quality through comprehensive provisions targeting air pollution control from both stationary and mobile sources. It establishes emission limits, control areas, occupational air quality limits, licensing requirements, measurement methods, reporting obligations, and penalties for non-compliance. The policy aims to protect human health, set standards for air quality, and ensure compliance with environmental regulations.', 'Kenya', 'climate', 'in_force', '2014-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_11', ARRAY['sdg8', 'other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg6', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ca2658c7-c099-5b4a-adb2-9c1c4982c162', 'Kenya Draft E-waste Regulations', 'Draft E-waste Regulations', 'This strategy provides a framework to guide stakeholders in the concerted efforts in sustainable management of E-waste in the country and hence build synergy among the various players.', 'This strategy provides a framework to guide stakeholders in the concerted efforts in sustainable management of E-waste in the country and hence build synergy among the various players.', 'This strategy provides a framework to guide stakeholders in the concerted efforts in sustainable management of E-waste in the country and hence build synergy among the various players.', 'Kenya', 'climate', 'in_force', '2013-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_12', ARRAY['other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('721c84a5-5fe2-529d-bf4b-959080a25491', 'Kenya Risk Management Guidlines', 'Risk Management Guidlines', 'The Central Bank of Kenya has put forward this document for the purpose of providing guidelines to all institutions on minimum requirements for risk management systems and frameworks.', 'The Central Bank of Kenya has put forward this document for the purpose of providing guidelines to all institutions on minimum requirements for risk management systems and frameworks.', 'The Central Bank of Kenya has put forward this document for the purpose of providing guidelines to all institutions on minimum requirements for risk management systems and frameworks.', 'Kenya', 'governance', 'in_force', '2013-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_2', ARRAY['kenya', 'mandatory', 'other sustainability policy', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('75848a60-1bfd-5791-90c2-7ace36a0e1f5', 'Kenya Eco-Rating Certification Guide', 'The Eco-Rating Certification Guide', 'The Eco-rating certification Scheme is a sustainable tourism certification program that aims to promote responsible tourism in Kenya. Launched in 2002 by Ecotourism Kenya in cooperation with tourism stakeholders in Kenya, the programs focus is to recognise best practices in environmental conservation, responsible resource use and socio-economic investment among tourism accommodation facilities by awarding qualified applicants assessed under the scheme with a Bronze, Silver or Gold eco-rating certification based on their performance.', 'The Eco-rating certification Scheme is a sustainable tourism certification program that aims to promote responsible tourism in Kenya. Launched in 2002 by Ecotourism Kenya in cooperation with tourism stakeholders in Kenya, the programs focus is to recognise best practices in environmental conservation, responsible resource use and socio-economic investment among tourism accommodation facilities by awarding qualified applicants assessed under the scheme with a Bronze, Silver or Gold eco-rating certification based on their performance.', 'The Eco-rating certification Scheme is a sustainable tourism certification program that aims to promote responsible tourism in Kenya. Launched in 2002 by Ecotourism Kenya in cooperation with tourism stakeholders in Kenya, the programs focus is to recognise best practices in environmental conservation, responsible resource use and socio-economic investment among tourism accommodation facilities by awarding qualified applicants assessed under the scheme with a Bronze, Silver or Gold eco-rating certification based on their performance.', 'Kenya', 'climate', 'in_force', '2013-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_9', ARRAY['other sustainability policy', 'kenya', 'regulations', 'sdg17', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ace9241d-f455-5534-bada-c34cbc81c44b', 'Kenya Capital Markets Act [Revised 2012]', 'The Capital Markets Act [Revised 2012]', 'These Guidelines are intended to provide the minimum standards required from shareholders, directors, chief executive officers and management of a listed company so as to promote high standards of conduct as well as ensure that they exercise their duties and responsibilities with clarity, assurance and effectiveness.', 'These Guidelines are intended to provide the minimum standards required from shareholders, directors, chief executive officers and management of a listed company so as to promote high standards of conduct as well as ensure that they exercise their duties and responsibilities with clarity, assurance and effectiveness.', 'These Guidelines are intended to provide the minimum standards required from shareholders, directors, chief executive officers and management of a listed company so as to promote high standards of conduct as well as ensure that they exercise their duties and responsibilities with clarity, assurance and effectiveness.', 'Kenya', 'governance', 'in_force', '2012-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_22', ARRAY['mandatory', 'other sustainability policy', 'kenya', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2ec51a24-2676-5643-a17c-f484785732f3', 'Kenya Biosafety Act', 'Biosafety Act, 2009', 'This document outlines an Act of the Kenyan Parliament to regulate activities in genetically modified organisms, to establish the National Biosafety Authority, and for connected purposes.', 'This document outlines an Act of the Kenyan Parliament to regulate activities in genetically modified organisms, to establish the National Biosafety Authority, and for connected purposes.', 'This document outlines an Act of the Kenyan Parliament to regulate activities in genetically modified organisms, to establish the National Biosafety Authority, and for connected purposes.', 'Kenya', 'nature', 'in_force', '2009-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_4', ARRAY['sdg2', 'other sustainability policy', 'kenya', 'regulations', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ec35afda-02d5-53f5-a262-badae7f899f4', 'Kenya Labour Relations Act', 'The Labour Relations Act', 'This document is concerned with an Act of the Kenyan Parliament to consolidate the law relating to trade unions and trade disputes, to provide for the registration, regulation, management and democratisation of trade unions and employers organisations or federations, to promote sound labour relations through the protection and promotion of freedom of association, the encouragement of effective collective bargaining and promotion of orderly and expeditious dispute settlement, conductive to social justice nad economic development and for connected purposes.', 'This document is concerned with an Act of the Kenyan Parliament to consolidate the law relating to trade unions and trade disputes, to provide for the registration, regulation, management and democratisation of trade unions and employers organisations or federations, to promote sound labour relations through the protection and promotion of freedom of association, the encouragement of effective collective bargaining and promotion of orderly and expeditious dispute settlement, conductive to social justice nad economic development and for connected purposes.', 'This document is concerned with an Act of the Kenyan Parliament to consolidate the law relating to trade unions and trade disputes, to provide for the registration, regulation, management and democratisation of trade unions and employers organisations or federations, to promote sound labour relations through the protection and promotion of freedom of association, the encouragement of effective collective bargaining and promotion of orderly and expeditious dispute settlement, conductive to social justice nad economic development and for connected purposes.', 'Kenya', 'social', 'in_force', '2007-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_18', ARRAY['sdg8', 'other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0f5564d7-d509-5aef-be11-143605f28a52', 'Kenya Occupational Safety and Health Act', 'The Occupational Safety and Health Act, 2007', 'This document outlines an Act of the Kenyan Parliament to provide for the safety, health and welfare of workers and all persons lawfully present at workplaces, to provide for the establishment of the National Council for Occupational Safety and Health and for connected purposes.', 'This document outlines an Act of the Kenyan Parliament to provide for the safety, health and welfare of workers and all persons lawfully present at workplaces, to provide for the establishment of the National Council for Occupational Safety and Health and for connected purposes.', 'This document outlines an Act of the Kenyan Parliament to provide for the safety, health and welfare of workers and all persons lawfully present at workplaces, to provide for the establishment of the National Council for Occupational Safety and Health and for connected purposes.', 'Kenya', 'social', 'in_force', '2007-01-01'::date, 'Kenya', 'https://www.carrotsandsticks.org/policies/90_20', ARRAY['sdg8', 'other sustainability policy', 'kenya', 'regulations', 'mandatory', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
